func parseMatcherDefinitions(d *caddyfile.Dispenser, matchers map[string]caddy.ModuleMap) error {
	d.Next() // advance to the first token

	// this is the "name" for "named matchers"
	definitionName := d.Val()

	if _, ok := matchers[definitionName]; ok {
		return fmt.Errorf("matcher is defined more than once: %s", definitionName)
	}
	matchers[definitionName] = make(caddy.ModuleMap)
	matcherLabel := definitionName[1:]

	// if the next token is quoted, we can assume it's not a matcher name
	// and that it's probably an 'expression' matcher
	if d.NextArg() {
		token := d.Token()
		if token.Quoted() {
			// since it was missing the matcher name, we insert a token
			// in front of the expression token itself
			expressionNameToken := caddyfile.Token{
				Text: "expression",
				File: d.File(),
				Line: d.Line(),
			}
			expressionTokens := make([]caddyfile.Token, 0, 2)
			expressionTokens = append(expressionTokens, expressionNameToken)
			expressionTokens = append(expressionTokens, token)

			matcherModuleName := "expression"
			moduleID := caddy.ModuleID("http.matchers." + matcherModuleName)
			mod, err := caddy.GetModule(string(moduleID))
			if err != nil {
				return fmt.Errorf("getting matcher module '%s': %v", matcherModuleName, err)
			}

			instance := mod.New()
			unm, ok := instance.(caddyfile.Unmarshaler)
			if !ok {
				return fmt.Errorf("matcher module '%s' is not a Caddyfile unmarshaler", matcherModuleName)
			}

			dispenser := caddyfile.NewDispenser(expressionTokens)
			dispenser.SetContext(caddyfile.MatcherNameCtxKey, matcherLabel)

			exprMatcher, isExpr := instance.(*caddyhttp.MatchExpression)
			if !isExpr {
				err = unm.UnmarshalCaddyfile(dispenser)
				if err != nil {
					return err
				}
			} else {
				dispenser.Next() // consume matcher name
				remainingArgs := dispenser.CountRemainingArgs()
				if remainingArgs > 1 {
					exprMatcher.Expr = strings.Join(dispenser.RemainingArgsRaw(), " ")
				} else if !dispenser.NextArg() {
					return dispenser.ArgErr()
				} else {
					exprMatcher.Expr = dispenser.Val()
					exprMatcher.Name = dispenser.GetContextString(caddyfile.MatcherNameCtxKey)
				}
			}

			rm, ok := instance.(caddyhttp.RequestMatcher)
			if !ok {
				return fmt.Errorf("matcher module '%s' is not a request matcher", matcherModuleName)
			}
			encoded, _ := json.Marshal(rm)
			matchers[definitionName][matcherModuleName] = encoded
			return nil
		}

		// if it wasn't quoted, then we need to rewind after calling
		// d.NextArg() so the below properly grabs the matcher name
		d.Prev()
	}

	// in case there are multiple instances of the same matcher, concatenate
	// their tokens (we expect that UnmarshalCaddyfile should be able to
	// handle more than one segment); otherwise, we'd overwrite other
	// instances of the matcher in this set
	tokensByMatcherName := make(map[string][]caddyfile.Token)
	for nesting := d.Nesting(); d.NextArg() || d.NextBlock(nesting); {
		matcherName := d.Val()
		segment := d.NextSegment()
		tokensByMatcherName[matcherName] = append(tokensByMatcherName[matcherName], segment...)
	}

	for matcherName, tokens := range tokensByMatcherName {
		dispenser := caddyfile.NewDispenser(tokens)
		dispenser.SetContext(caddyfile.MatcherNameCtxKey, matcherLabel)

		moduleID := caddy.ModuleID("http.matchers." + matcherName)
		mod, err := caddy.GetModule(string(moduleID))
		if err != nil {
			return fmt.Errorf("getting matcher module '%s': %v", matcherName, err)
		}
		unm, ok := mod.New().(caddyfile.Unmarshaler)
		if !ok {
			return fmt.Errorf("matcher module '%s' is not a Caddyfile unmarshaler", matcherName)
		}
		err = unm.UnmarshalCaddyfile(dispenser)
		if err != nil {
			return err
		}
		rm, ok := unm.(caddyhttp.RequestMatcher)
		if !ok {
			return fmt.Errorf("matcher module '%s' is not a request matcher", matcherName)
		}

		encoded, _ := json.Marshal(rm)
		matchers[definitionName][matcherName] = encoded
	}
	return nil
}

func encodeMatcherSet(matchers map[string]caddyhttp.RequestMatcher) (caddy.ModuleMap, error) {
	msEncoded := make(caddy.ModuleMap)
	for matcherName, val := range matchers {
		jsonBytes, err := json.Marshal(val)
		if err != nil {
			return nil, fmt.Errorf("marshaling matcher set %#v: %v", matchers, err)
		}
		msEncoded[matcherName] = jsonBytes
	}
	return msEncoded, nil
}

